func (a *AuthServer) updateRemoteClusterStatus(remoteCluster services.RemoteCluster) error {
	// fetch tunnel connections for the cluster to update runtime status
	connections, err := a.GetTunnelConnections(remoteCluster.GetName())
	if err != nil {
		return trace.Wrap(err)
	}

	status := teleport.RemoteClusterStatusOffline
	heartbeat := remoteCluster.GetLastHeartbeat().UTC()
	if len(connections) > 0 {
		status = teleport.RemoteClusterStatusOnline
		lastConn, err := services.LatestTunnelConnection(connections)
		if err != nil {
			return trace.Wrap(err)
		}
		lastHeartbeat := lastConn.GetLastHeartbeat().UTC()
		if lastHeartbeat.After(heartbeat) {
			heartbeat = lastHeartbeat
		}
	}

	currentHeartbeat := remoteCluster.GetLastHeartbeat()
	if remoteCluster.GetConnectionStatus() != status || currentHeartbeat != heartbeat {
		remoteCluster.SetConnectionStatus(status)
		remoteCluster.SetLastHeartbeat(heartbeat)
		if err := a.Presence.UpdateRemoteCluster(context.TODO(), remoteCluster); err != nil {
			return trace.Wrap(err)
		}
	}
	return nil
}

